    /// <summary>
    /// The bell court in front of the old crypt: where the wanderer may stand. The rows are baked from the court's own
    /// models (Tools/Art/aschenwacht/court_grid.py): every wall, rock and figure blocks the cells it covers between knee
    /// and head height, the ground's edge ends the court, and the wanderer's radius is already added. One character
    /// is a cell of 200 mm; row 0 is the southern edge, column 0 the western.
    /// </summary>
    public static class CourtLayout
    {
        public const long CellMm = 200L;
        public const long HalfMm = 12000L;
        /// <summary>Inside the chapel's nave, where the stair from the crypt ends.</summary>
        public const long SpawnXmm = 0L, SpawnZmm = -4000L;
        /// <summary>The northern end of the pilgrim path: from here the way leads down to the village.</summary>
        public const long ExitXmm = 0L, ExitZmm = 8000L;

        public static bool CanStand(long x, long z)
        {
            long column = FloorDiv(x + HalfMm, CellMm), row = FloorDiv(z + HalfMm, CellMm);
            if (column < 0 || row < 0 || row >= Rows.Length || column >= Rows[0].Length) return false;
            return Rows[(int)row][(int)column] == '.';
        }

        private static long FloorDiv(long value, long step) { return value >= 0 ? value / step : -((-value + step - 1) / step); }

